import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:negative @smoke submits contact form with malformed email', async ({ page }) => {
  await opGoto(page, '/contact')
  await opFill(page, 'Name', 'Jane Doe')
  await opFill(page, 'Email', 'not-an-email')
  await opFill(page, 'Which service are you interested in', 'Testing')
  await opPress(page, 'Tab')
  await opFill(page, 'Message', 'Hello')
  await opClick(page, 'button', 'Send message')
  await opSeen(page, 'dialog', 'Please enter a valid email address')
})
